/*
 * A257880  Sequence (d(n)) generated by Rule 1 (in Comments) with a(1) = 2
 *          and d(1) = 0.
 * https://oeis.org/A257880
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, sign
 * Formula:   d(n) computed by Rule 1 with a(1) = 2 and d(1) = 0
 * Range:     i8 n <= 98, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The function returns the nth term of sequence A257880. */

/* Standard headers */
#include <stdlib.h>
#include <stdbool.h>

/* Forward declaration of helper function */
static bool contains_seq(const seq_t *arr, size_t len, seq_t val);

/* Static storage for the sequences */
static seq_t *a_seq = NULL;   /* a(k) values */
static seq_t *d_seq = NULL;   /* d(k) values */
static size_t seq_len = 0;    /* current number of stored elements */
static size_t seq_cap = 0;    /* allocated capacity */

/* Ensure capacity for at least 'need' elements */
static void ensure_capacity(size_t need)
{
    if (need <= seq_cap)
        return;
    size_t new_cap = (need * 2 > 4) ? (need * 2) : 4;
    a_seq = (seq_t *)realloc(a_seq, new_cap * sizeof(seq_t));
    d_seq = (seq_t *)realloc(d_seq, new_cap * sizeof(seq_t));
    seq_cap = new_cap;
}

/* Linear search for val in arr[0..len-1] */
static bool contains_seq(const seq_t *arr, size_t len, seq_t val)
{
    for (size_t i = 0; i < len; ++i)
        if (arr[i] == val)
            return true;
    return false;
}

/* Main function required by the harness */
seq_t a(idx_t n)
{
    /* n is 1‑based, must be >=1 */
    if (n == 0) {
        /* safety, never used in a valid sequence */
        return (seq_t)0;
    }

    /* Initialize on first call */
    if (seq_len == 0) {
        ensure_capacity(4);
        a_seq[0] = (seq_t)2;   /* a(1) = 2 */
        d_seq[0] = (seq_t)0;   /* d(1) = 0 */
        seq_len = 1;
    }

    /* Extend the sequences up to index n */
    while (seq_len < (size_t)n) {
        size_t k = seq_len;           /* current k is seq_len (1‑based) */
        seq_t a_k = a_seq[k - 1];     /* a(k) */

        seq_t chosen_h = 0;
        bool found = false;

        /* Step 1: search for negative h (inclusive lower bound) */
        seq_t lower = (seq_t)1 - a_k;         /* 1 - a(k) */
        for (seq_t h = -1; h < 0 && h >= lower; --h) {
            if (!contains_seq(d_seq, seq_len, h) &&
                !contains_seq(a_seq, seq_len, a_k + h)) {
                chosen_h = h;
                found = true;
                break; /* greatest such h found */
            }
        }

        /* Step 2: if no negative h, find least positive h */
        if (!found) {
            for (seq_t h = (seq_t)1; ; ++h) {
                if (!contains_seq(d_seq, seq_len, h) &&
                    !contains_seq(a_seq, seq_len, a_k + h)) {
                    chosen_h = h;
                    break;
                }
            }
        }

        /* Append new elements */
        ensure_capacity(seq_len + 1);
        a_seq[seq_len] = a_k + chosen_h;
        d_seq[seq_len] = chosen_h;
        ++seq_len;
    }

    /* d(n) is stored at index n-1 */
    return d_seq[n - 1];
}
